// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title OrderPriceVolumeSet
/// @notice Library for tracking user orders by order ID, price, and volume
library OrderPriceVolumeSet {
    struct OPVnode {
        bytes32 _orderId;
        uint256 _price;  // Price in collateral units per full outcome token
        uint256 _volume;
    }

    struct OPVset {
        mapping(address => OPVnode[]) _orders;
        mapping(bytes32 => uint256) _indexes;
    }

    function _contains(OPVset storage set, bytes32 orderId)
        internal
        view
        returns (bool)
    {
        return set._indexes[orderId] != 0;
    }

    function _at(
        OPVset storage set,
        address userAddress,
        uint256 index
    ) internal view returns (OPVnode memory) {
        return set._orders[userAddress][index];
    }

    function _add(
        OPVset storage set,
        address userAddress,
        bytes32 orderId,
        uint256 price,
        uint256 volume
    ) internal returns (bool) {
        if (!_contains(set, orderId)) {
            set._orders[userAddress].push(OPVnode(orderId, price, volume));
            set._indexes[orderId] = set._orders[userAddress].length;
            return true;
        } else {
            return false;
        }
    }

    function _remove(
        OPVset storage set,
        address userAddress,
        bytes32 orderId
    ) internal returns (bool) {
        uint256 orderIdIndex = set._indexes[orderId];

        if (orderIdIndex != 0) {
            uint256 toDeleteIndex = orderIdIndex - 1;
            uint256 lastIndex = set._orders[userAddress].length - 1;

            if (lastIndex != toDeleteIndex) {
                OPVnode memory lastOPVnode = set._orders[userAddress][
                    lastIndex
                ];

                set._orders[userAddress][toDeleteIndex] = lastOPVnode;
                set._indexes[lastOPVnode._orderId] = orderIdIndex;
            }

            set._orders[userAddress].pop();
            delete set._indexes[orderId];

            return true;
        } else {
            return false;
        }
    }

    function _addVolume(
        OPVset storage set,
        address userAddress,
        bytes32 orderId,
        uint256 volume
    ) internal returns (bool) {
        uint256 orderIdIndex = set._indexes[orderId];

        if (orderIdIndex != 0) {
            set._orders[userAddress][orderIdIndex - 1]._volume += volume;
            return true;
        } else {
            return false;
        }
    }

    function _subVolume(
        OPVset storage set,
        address userAddress,
        bytes32 orderId,
        uint256 volume
    ) internal returns (bool) {
        uint256 orderIdIndex = set._indexes[orderId];

        if (orderIdIndex != 0) {
            set._orders[userAddress][orderIdIndex - 1]._volume -= volume;
            return true;
        } else {
            return false;
        }
    }
}

contracts/orderbook/MondaloreOrderBook.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/Address.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {OrderBookLinkedList} from "../libraries/OrderBookLinkedList.sol";
import {OrderPriceVolumeSet} from "../libraries/OrderPriceVolumeSet.sol";

interface IMondaloreOrderBookFactory {
    function isMarket(address market) external view returns (bool);
    function isOutcomeTokenForMarket(address market, address token) external view returns (bool);
}

interface IMondaloreMarketCollateral {
    function collateralAddress() external view returns (address);
    function collateralDecimals() external view returns (uint8);
}

/// @title MondaloreOrderBook
/// @notice On-chain CLOB for trading any outcome token registered on MondaloreParimutuelMarketFactory.
/// @dev No minting — only transfers existing tokens between users.
///      Matching crosses price levels (CLOB-style): incoming sell hits bids at >= limit;
///      incoming buy hits asks at <= limit. Per-fill fees apply to buyer and seller (same bps).
///      Collateral is resolved per-market and supports both ERC20 and native ETH.
contract MondaloreOrderBook is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using OrderBookLinkedList for OrderBookLinkedList.LinkedList;
    using OrderPriceVolumeSet for OrderPriceVolumeSet.OPVset;

    IMondaloreOrderBookFactory public immutable marketFactory;
    /// @notice Receives all accumulated fees via `withdrawFees` (immutable; set at deploy).
    address public immutable treasury;

    /// @notice Fee in basis points ( / 10_000 ) applied to **each side** on matched notional.
    uint16 public feeRate;
    mapping(address => uint256) public accumulatedFeeErc20;
    uint256 public accumulatedFeeNative;

    // Order book: market => token => price => orders
    mapping(address => mapping(address => mapping(uint256 => OrderBookLinkedList.LinkedList)))
        public sellOrderBook;
    mapping(address => mapping(address => mapping(uint256 => OrderBookLinkedList.LinkedList)))
        public buyOrderBook;

    // User orders: market => token => user => [orders]
    mapping(address => mapping(address => OrderPriceVolumeSet.OPVset)) private _sellOrders;
    mapping(address => mapping(address => OrderPriceVolumeSet.OPVset)) private _buyOrders;

    // Active prices — unsorted sets, sorted in memory at match time.
    mapping(address => mapping(address => uint256[])) private _sellPrices;
    mapping(address => mapping(address => uint256[])) private _buyPrices;
    mapping(address => mapping(address => mapping(uint256 => bool))) private _activePrices;

    // Events
    event OrderPlaced(
        address indexed market,
        address indexed token,
        address indexed user,
        uint256 price,
        uint256 amount,
        bytes32 orderId,
        bool isBuy
    );

    event OrderMatched(
        address indexed market,
        address indexed token,
        address indexed maker,
        address taker,
        uint256 price,
        uint256 amount
    );

    event OrderCancelled(
        address indexed market,
        address indexed token,
        address indexed user,
        uint256 price,
        bytes32 orderId
    );

    event FeesWithdrawn(address indexed collateral, address indexed recipient, uint256 amount);

    error ZeroAddress();
    error OnlyTreasury();

    constructor(
        address _marketFactory,
        address _owner,
        address _treasury
    ) Ownable(_owner) {
        if (_marketFactory == address(0) || _owner == address(0) || _treasury == address(0)) {
            revert ZeroAddress();
        }
        marketFactory = IMondaloreOrderBookFactory(_marketFactory);
        treasury = _treasury;
        feeRate = 50; // 0.5% per side (basis points / 10_000)
    }

    /// @notice Set per-side fee in basis points. Owner only.
    function setFeeRate(uint16 _feeRate) external onlyOwner {
        require(_feeRate <= 1000, "Fee too high");
        feeRate = _feeRate;
    }

    // ─── Escrow helpers ───────────────────────────────────────────────────────

    /// @notice Max collateral escrow required to buy `tokenAmount` tokens at `limitPrice`.
    /// @param tokenDec Decimals of the outcome token being purchased.
    function _escrowForBuy(uint256 tokenAmount, uint256 limitPrice, uint8 tokenDec) internal view returns (uint256) {
        uint256 maxNotional = (tokenAmount * limitPrice) / (10 ** uint256(tokenDec));
        return maxNotional + (maxNotional * feeRate) / 10000;
    }

    /// @notice Collateral escrow the buyer pays for `matchTok` tokens at `price`.
    function _buyerEscrowForTokens(
        uint256 matchTok,
        uint256 price,
        uint16 _feeRate,
        uint8 tokenDec
    ) internal pure returns (uint256) {
        uint256 n = (matchTok * price) / (10 ** uint256(tokenDec));
        return n + (n * _feeRate) / 10000;
    }

    /// @notice Largest `matchTok` in [0, cap] such that `_buyerEscrowForTokens <= escrowLimit`.
    /// @dev Binary search — avoids stacked floor-division undercount.
    function _maxMatchTokUnderEscrow(
        uint256 escrowLimit,
        uint256 price,
        uint256 cap,
        uint16 _feeRate,
        uint8 tokenDec
    ) internal pure returns (uint256) {
        if (cap == 0 || escrowLimit == 0 || price == 0) return 0;
        uint256 hi = cap;
        unchecked {
            uint256 mulCap = type(uint256).max / price;
            if (hi > mulCap) hi = mulCap;
        }
        uint256 lo = 0;
        while (lo < hi) {
            uint256 mid = (lo + hi + 1) / 2;
            if (_buyerEscrowForTokens(mid, price, _feeRate, tokenDec) <= escrowLimit) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        return lo;
    }

    // ─── Collateral helpers ───────────────────────────────────────────────────

    function _marketCollateral(address market) internal view returns (address collateral, uint8 colDec) {
        IMondaloreMarketCollateral m = IMondaloreMarketCollateral(market);
        collateral = m.collateralAddress();
        colDec = m.collateralDecimals();
    }

    function _pullCollateral(address collateral, address from, uint256 amount) internal {
        if (collateral == address(0)) {
            require(msg.value >= amount, "Insufficient ETH");
            if (msg.value > amount) {
                Address.sendValue(payable(from), msg.value - amount);
            }
        } else {
            require(msg.value == 0, "No ETH for ERC20 market");
            IERC20(collateral).safeTransferFrom(from, address(this), amount);
        }
    }

    function _sendCollateral(address collateral, address to, uint256 amount) internal {
        if (collateral == address(0)) {
            Address.sendValue(payable(to), amount);
        } else {
            IERC20(collateral).safeTransfer(to, amount);
        }
    }

    // ─── Order placement ──────────────────────────────────────────────────────

    /// @notice Place a sell order.
    function placeSellOrder(
        address market,
        address token,
        uint256 price,
        uint256 amount
    ) external returns (bytes32 orderId) {
        require(marketFactory.isMarket(market), "Invalid market");
        require(marketFactory.isOutcomeTokenForMarket(market, token), "Invalid token for market");
        require(price > 0, "Price must be > 0");
        require(amount > 0, "Amount must be > 0");

        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);

        uint8 tokenDec = IERC20Metadata(token).decimals();
        uint256 remainingAmount = _matchSellOrder(market, token, price, amount, tokenDec);

        if (remainingAmount > 0) {
            if (sellOrderBook[market][token][price].length == 0) {
                orderId = sellOrderBook[market][token][price].initHead(msg.sender, remainingAmount);
                _addSellPrice(market, token, price);
            } else {
                orderId = sellOrderBook[market][token][price].addNode(msg.sender, remainingAmount);
            }

            _sellOrders[market][token]._add(msg.sender, orderId, price, remainingAmount);
            emit OrderPlaced(market, token, msg.sender, price, remainingAmount, orderId, false);
        }
    }

    /// @notice Place a buy order. Send ETH for native-collateral markets; approve ERC20 otherwise.
    function placeBuyOrder(
        address market,
        address token,
        uint256 price,
        uint256 amount
    ) external payable returns (bytes32 orderId) {
        require(marketFactory.isMarket(market), "Invalid market");
        require(marketFactory.isOutcomeTokenForMarket(market, token), "Invalid token for market");
        require(price > 0, "Price must be > 0");
        require(amount > 0, "Amount must be > 0");

        (address collateral, ) = _marketCollateral(market);
        uint8 tokenDec = IERC20Metadata(token).decimals();
        uint256 escrowTotal = _escrowForBuy(amount, price, tokenDec);

        _pullCollateral(collateral, msg.sender, escrowTotal);

        (uint256 remainingTokens, uint256 escrowLeft) = _matchBuyOrder(
            market, token, price, amount, escrowTotal, collateral, tokenDec
        );

        // Refund price-improvement surplus.
        uint256 escrowNeeded = remainingTokens > 0 ? _escrowForBuy(remainingTokens, price, tokenDec) : 0;
        if (escrowLeft > escrowNeeded) {
            _sendCollateral(collateral, msg.sender, escrowLeft - escrowNeeded);
            escrowLeft = escrowNeeded;
        }

        if (remainingTokens > 0) {
            if (buyOrderBook[market][token][price].length == 0) {
                orderId = buyOrderBook[market][token][price].initHead(msg.sender, escrowLeft);
                _addBuyPrice(market, token, price);
            } else {
                orderId = buyOrderBook[market][token][price].addNode(msg.sender, escrowLeft);
            }

            _buyOrders[market][token]._add(msg.sender, orderId, price, escrowLeft);
            emit OrderPlaced(market, token, msg.sender, price, remainingTokens, orderId, true);
        }
    }

    // ─── Order cancellation ───────────────────────────────────────────────────

    /// @notice Cancel a sell order; returns escrowed outcome tokens.
    function cancelSellOrder(
        address market,
        address token,
        uint256 price,
        bytes32 orderId
    ) external {
        OrderBookLinkedList.Order memory o = sellOrderBook[market][token][price]
            .nodes[orderId]
            .order;
        require(msg.sender == o.seller, "Not order owner");

        IERC20(token).safeTransfer(msg.sender, o.amount);

        sellOrderBook[market][token][price].deleteNode(orderId);
        _sellOrders[market][token]._remove(msg.sender, orderId);
        _removePrice(market, token, price, true);

        emit OrderCancelled(market, token, msg.sender, price, orderId);
    }

    /// @notice Cancel a buy order; returns escrowed collateral.
    function cancelBuyOrder(
        address market,
        address token,
        uint256 price,
        bytes32 orderId
    ) external {
        OrderBookLinkedList.Order memory o = buyOrderBook[market][token][price]
            .nodes[orderId]
            .order;
        require(msg.sender == o.seller, "Not order owner");

        (address collateral, ) = _marketCollateral(market);
        _sendCollateral(collateral, msg.sender, o.amount);

        buyOrderBook[market][token][price].deleteNode(orderId);
        _buyOrders[market][token]._remove(msg.sender, orderId);
        _removePrice(market, token, price, false);

        emit OrderCancelled(market, token, msg.sender, price, orderId);
    }

    // ─── Matching ─────────────────────────────────────────────────────────────

    /// @notice Match incoming sell against resting bids at >= sellLimitPrice (FIFO per level).
    function _matchSellOrder(
        address market,
        address token,
        uint256 sellLimitPrice,
        uint256 sellAmount,
        uint8 tokenDec
    ) internal returns (uint256 remainingAmount) {
        remainingAmount = sellAmount;
        (address collateral, ) = _marketCollateral(market);
        IERC20 tokenContract = IERC20(token);
        uint256[] memory bids = _loadSortedDesc(_buyPrices[market][token]);

        for (uint256 idx = 0; idx < bids.length && remainingAmount > 0; idx++) {
            uint256 bidPrice = bids[idx];
            if (bidPrice < sellLimitPrice) break;

            while (buyOrderBook[market][token][bidPrice].length > 0 && remainingAmount > 0) {
                bytes32 head_ = buyOrderBook[market][token][bidPrice].head;
                uint256 buyEscrow = buyOrderBook[market][token][bidPrice].nodes[head_].order.amount;
                OrderBookLinkedList.Order memory buyOrder = buyOrderBook[market][token][bidPrice]
                    .nodes[head_]
                    .order;

                uint256 matchTok = _maxMatchTokUnderEscrow(buyEscrow, bidPrice, remainingAmount, feeRate, tokenDec);
                if (matchTok == 0) return remainingAmount;

                uint256 n = (matchTok * bidPrice) / (10 ** uint256(tokenDec));
                uint256 buyerFee = (n * feeRate) / 10000;
                uint256 sellerFee = (n * feeRate) / 10000;

                uint256 escrowDec = n + buyerFee;
                if (collateral == address(0)) {
                    accumulatedFeeNative += buyerFee + sellerFee;
                } else {
                    accumulatedFeeErc20[collateral] += buyerFee + sellerFee;
                }

                if (escrowDec >= buyEscrow) {
                    buyOrderBook[market][token][bidPrice].popHead();
                    _buyOrders[market][token]._remove(buyOrder.seller, head_);
                    _removePrice(market, token, bidPrice, false);
                } else {
                    buyOrderBook[market][token][bidPrice].nodes[head_].order.amount = buyEscrow - escrowDec;
                    _buyOrders[market][token]._subVolume(buyOrder.seller, head_, escrowDec);
                }

                tokenContract.safeTransfer(buyOrder.seller, matchTok);
                _sendCollateral(collateral, msg.sender, n - sellerFee);

                emit OrderMatched(market, token, buyOrder.seller, msg.sender, bidPrice, matchTok);

                remainingAmount -= matchTok;
            }
        }
    }

    /// @notice Match incoming buy against resting asks at <= buyLimitPrice (FIFO per level).
    function _matchBuyOrder(
        address market,
        address token,
        uint256 buyLimitPrice,
        uint256 buyTokenAmount,
        uint256 buyerEscrowIn,
        address collateral,
        uint8 tokenDec
    ) internal returns (uint256 remainingTokens, uint256 escrowOut) {
        remainingTokens = buyTokenAmount;
        escrowOut = buyerEscrowIn;
        IERC20 tokenContract = IERC20(token);
        uint256[] memory asks = _loadSortedAsc(_sellPrices[market][token]);

        for (uint256 idx = 0; idx < asks.length && remainingTokens > 0 && escrowOut > 0; idx++) {
            uint256 askPrice = asks[idx];
            if (askPrice > buyLimitPrice) break;

            while (sellOrderBook[market][token][askPrice].length > 0 && remainingTokens > 0 && escrowOut > 0) {
                bytes32 head_ = sellOrderBook[market][token][askPrice].head;
                uint256 sellTokAvail = sellOrderBook[market][token][askPrice].nodes[head_].order.amount;
                OrderBookLinkedList.Order memory sellOrder = sellOrderBook[market][token][askPrice]
                    .nodes[head_]
                    .order;

                uint256 cap = remainingTokens < sellTokAvail ? remainingTokens : sellTokAvail;
                uint256 matchTok = _maxMatchTokUnderEscrow(escrowOut, askPrice, cap, feeRate, tokenDec);
                if (matchTok == 0) return (remainingTokens, escrowOut);

                uint256 n = (matchTok * askPrice) / (10 ** uint256(tokenDec));
                uint256 buyerFee = (n * feeRate) / 10000;
                uint256 sellerFee = (n * feeRate) / 10000;

                uint256 escrowDec = n + buyerFee;
                if (collateral == address(0)) {
                    accumulatedFeeNative += buyerFee + sellerFee;
                } else {
                    accumulatedFeeErc20[collateral] += buyerFee + sellerFee;
                }
                escrowOut -= escrowDec;

                if (matchTok == sellTokAvail) {
                    sellOrderBook[market][token][askPrice].popHead();
                    _sellOrders[market][token]._remove(sellOrder.seller, head_);
                    _removePrice(market, token, askPrice, true);
                } else {
                    sellOrderBook[market][token][askPrice].nodes[head_].order.amount = sellTokAvail - matchTok;
                    _sellOrders[market][token]._subVolume(sellOrder.seller, head_, matchTok);
                }

                tokenContract.safeTransfer(msg.sender, matchTok);
                _sendCollateral(collateral, sellOrder.seller, n - sellerFee);

                emit OrderMatched(market, token, sellOrder.seller, msg.sender, askPrice, matchTok);

                remainingTokens -= matchTok;
            }
        }
    }

    // ─── Price set management ─────────────────────────────────────────────────

    function _addSellPrice(address market, address token, uint256 price) internal {
        if (!_activePrices[market][token][price]) {
            _activePrices[market][token][price] = true;
            _sellPrices[market][token].push(price);
        }
    }

    function _addBuyPrice(address market, address token, uint256 price) internal {
        if (!_activePrices[market][token][price]) {
            _activePrices[market][token][price] = true;
            _buyPrices[market][token].push(price);
        }
    }

    function _removePrice(address market, address token, uint256 price, bool isSell) internal {
        if (sellOrderBook[market][token][price].length == 0 &&
            buyOrderBook[market][token][price].length == 0) {
            _activePrices[market][token][price] = false;
            if (isSell) {
                _removeFromArray(_sellPrices[market][token], price);
            } else {
                _removeFromArray(_buyPrices[market][token], price);
            }
        }
    }

    /// @dev Swap-pop removal — O(n) SLOADs, 1 SSTORE, no shifting.
    function _removeFromArray(uint256[] storage arr, uint256 price) internal {
        for (uint256 i = 0; i < arr.length; i++) {
            if (arr[i] == price) {
                arr[i] = arr[arr.length - 1];
                arr.pop();
                return;
            }
        }
    }

    /// @dev Copy storage array to memory and insertion-sort descending. No SSTOREs.
    function _loadSortedDesc(uint256[] storage src) internal view returns (uint256[] memory arr) {
        arr = new uint256[](src.length);
        for (uint256 i = 0; i < src.length; i++) arr[i] = src[i];
        for (uint256 i = 1; i < arr.length; i++) {
            uint256 key = arr[i];
            uint256 j = i;
            while (j > 0 && arr[j - 1] < key) {
                arr[j] = arr[j - 1];
                j--;
            }
            arr[j] = key;
        }
    }

    /// @dev Copy storage array to memory and insertion-sort ascending. No SSTOREs.
    function _loadSortedAsc(uint256[] storage src) internal view returns (uint256[] memory arr) {
        arr = new uint256[](src.length);
        for (uint256 i = 0; i < src.length; i++) arr[i] = src[i];
        for (uint256 i = 1; i < arr.length; i++) {
            uint256 key = arr[i];
            uint256 j = i;
            while (j > 0 && arr[j - 1] > key) {
                arr[j] = arr[j - 1];
                j--;
            }
            arr[j] = key;
        }
    }

    // ─── Fee withdrawal ───────────────────────────────────────────────────────

    /// @notice Pull accumulated fees to `treasury`. Callable **only** by `treasury`.
    /// @param collateralAsset ERC20 address, or address(0) for native ETH.
    function withdrawFees(address collateralAsset) external nonReentrant {
        if (msg.sender != treasury) revert OnlyTreasury();
        uint256 fee;
        if (collateralAsset == address(0)) {
            fee = accumulatedFeeNative;
            accumulatedFeeNative = 0;
            if (fee > 0) Address.sendValue(payable(treasury), fee);
        } else {
            fee = accumulatedFeeErc20[collateralAsset];
            accumulatedFeeErc20[collateralAsset] = 0;
            if (fee > 0) IERC20(collateralAsset).safeTransfer(treasury, fee);
        }
        emit FeesWithdrawn(collateralAsset, treasury, fee);
    }

    // ─── View functions ───────────────────────────────────────────────────────

    /// @notice Best bid price (highest active bid).
    function getBestBid(address market, address token) external view returns (uint256 best) {
        uint256[] storage prices = _buyPrices[market][token];
        for (uint256 i = 0; i < prices.length; i++) {
            if (buyOrderBook[market][token][prices[i]].length > 0 && prices[i] > best) {
                best = prices[i];
            }
        }
    }

    /// @notice Best ask price (lowest active ask).
    function getBestAsk(address market, address token) external view returns (uint256 best) {
        uint256[] storage prices = _sellPrices[market][token];
        for (uint256 i = 0; i < prices.length; i++) {
            if (sellOrderBook[market][token][prices[i]].length > 0 && (best == 0 || prices[i] < best)) {
                best = prices[i];
            }
        }
    }

    /// @notice All open sell orders for a user on a given market/token pair.
    function getUserSellOrders(address market, address token, address user)
        external
        view
        returns (OrderPriceVolumeSet.OPVnode[] memory)
    {
        return _sellOrders[market][token]._orders[user];
    }

    /// @notice All open buy orders for a user on a given market/token pair.
    function getUserBuyOrders(address market, address token, address user)
        external
        view
        returns (OrderPriceVolumeSet.OPVnode[] memory)
    {
        return _buyOrders[market][token]._orders[user];
    }

    /// @notice Snapshot of the order book — all active price levels with aggregated volume.
    function getOrderBookSnapshot(address market, address token)
        external
        view
        returns (
            uint256[] memory bidPrices,
            uint256[] memory bidVolumes,
            uint256[] memory askPrices,
            uint256[] memory askVolumes
        )
    {
        uint256[] storage bps = _buyPrices[market][token];
        uint256[] storage aps = _sellPrices[market][token];

        bidPrices  = new uint256[](bps.length);
        bidVolumes = new uint256[](bps.length);
        askPrices  = new uint256[](aps.length);
        askVolumes = new uint256[](aps.length);

        for (uint256 i = 0; i < bps.length; i++) {
            bidPrices[i] = bps[i];
            bytes32 curr = buyOrderBook[market][token][bps[i]].head;
            while (curr != bytes32(0)) {
                bidVolumes[i] += buyOrderBook[market][token][bps[i]].nodes[curr].order.amount;
                curr = buyOrderBook[market][token][bps[i]].nodes[curr].next;
            }
        }

        for (uint256 i = 0; i < aps.length; i++) {
            askPrices[i] = aps[i];
            bytes32 curr = sellOrderBook[market][token][aps[i]].head;
            while (curr != bytes32(0)) {
                askVolumes[i] += sellOrderBook[market][token][aps[i]].nodes[curr].order.amount;
                curr = sellOrderBook[market][token][aps[i]].nodes[curr].next;
            }
        }
    }

    receive() external payable {}
}

contracts/orderbook/MondaloreVParimutuel.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/Address.sol";
import {OrderBookLinkedList} from "../libraries/OrderBookLinkedList.sol";
import {OrderPriceVolumeSet} from "../libraries/OrderPriceVolumeSet.sol";

interface IMondaloreBookFactory {
    function isMarket(address market) external view returns (bool);
    function isOutcomeTokenForMarket(address market, address token) external view returns (bool);
}

interface IMondaloreMarketCollateral {
    function collateralAddress() external view returns (address);
    function collateralDecimals() external view returns (uint8);
}

/// @title MondaloreVParimutuelOrderBook
/// @notice Secondary trading for any outcome token registered on MondaloreParimutuelMarketFactory (replaces bound/break-only books).
/// @dev Collateral is read per market (ERC20 or native ETH). Price × amount uses outcome token decimals.
contract MondaloreVParimutuelOrderBook is Ownable {
    using SafeERC20 for IERC20;
    using OrderBookLinkedList for OrderBookLinkedList.LinkedList;
    using OrderPriceVolumeSet for OrderPriceVolumeSet.OPVset;

    IMondaloreBookFactory public immutable marketFactory;

    uint16 public feeRate;
    mapping(address => uint256) public accumulatedFeeErc20;
    uint256 public accumulatedFeeNative;

    mapping(address => mapping(address => mapping(uint256 => OrderBookLinkedList.LinkedList))) public sellOrderBook;
    mapping(address => mapping(address => mapping(uint256 => OrderBookLinkedList.LinkedList))) public buyOrderBook;

    mapping(address => mapping(address => OrderPriceVolumeSet.OPVset)) private _sellOrders;
    mapping(address => mapping(address => OrderPriceVolumeSet.OPVset)) private _buyOrders;

    mapping(address => mapping(address => uint256[])) private _sellPrices;
    mapping(address => mapping(address => uint256[])) private _buyPrices;
    mapping(address => mapping(address => mapping(uint256 => bool))) private _activePrices;

    event OrderPlaced(
        address indexed market,
        address indexed token,
        address indexed user,
        uint256 price,
        uint256 amount,
        bytes32 orderId,
        bool isBuy
    );
    event OrderMatched(
        address indexed market,
        address indexed token,
        address indexed maker,
        address taker,
        uint256 price,
        uint256 amount
    );
    event OrderCancelled(
        address indexed market,
        address indexed token,
        address indexed user,
        uint256 price,
        bytes32 orderId
    );

    constructor(address _marketFactory, address _owner) Ownable(_owner) {
        marketFactory = IMondaloreBookFactory(_marketFactory);
        feeRate = 50;
    }

    function setFeeRate(uint16 _feeRate) external onlyOwner {
        require(_feeRate <= 1000, "Fee too high");
        feeRate = _feeRate;
    }

    function placeSellOrder(address market, address token, uint256 price, uint256 amount) external returns (bytes32 orderId) {
        _validate(market, token);
        require(price > 0 && amount > 0, "Args");

        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);

        uint256 remainingAmount = _matchSellOrder(market, token, price, amount);

        if (remainingAmount > 0) {
            if (sellOrderBook[market][token][price].length == 0) {
                orderId = sellOrderBook[market][token][price].initHead(msg.sender, remainingAmount);
                _addSellPrice(market, token, price);
            } else {
                orderId = sellOrderBook[market][token][price].addNode(msg.sender, remainingAmount);
            }
            _sellOrders[market][token]._add(msg.sender, orderId, price, remainingAmount);
            emit OrderPlaced(market, token, msg.sender, price, remainingAmount, orderId, false);
        }
    }

    function placeBuyOrder(address market, address token, uint256 price, uint256 amount) external payable returns (bytes32 orderId) {
        _validate(market, token);
        require(price > 0 && amount > 0, "Args");

        (address collateral, uint8 td) = _marketAndTokenDecimals(market, token);
        uint256 quote = _quote(amount, price, td);
        uint256 fee = (quote * feeRate) / 10000;
        uint256 need = quote + fee;

        if (collateral == address(0)) {
            require(msg.value >= need, "ETH");
            if (msg.value > need) {
                Address.sendValue(payable(msg.sender), msg.value - need);
            }
            accumulatedFeeNative += fee;
        } else {
            require(msg.value == 0, "No ETH");
            IERC20(collateral).safeTransferFrom(msg.sender, address(this), need);
            accumulatedFeeErc20[collateral] += fee;
        }

        uint256 remainingAmount = _matchBuyOrder(market, token, price, amount, collateral);

        if (remainingAmount > 0) {
            uint256 remQuote = _quote(remainingAmount, price, td);
            if (buyOrderBook[market][token][price].length == 0) {
                orderId = buyOrderBook[market][token][price].initHead(msg.sender, remQuote);
                _addBuyPrice(market, token, price);
            } else {
                orderId = buyOrderBook[market][token][price].addNode(msg.sender, remQuote);
            }
            _buyOrders[market][token]._add(msg.sender, orderId, price, remQuote);
            emit OrderPlaced(market, token, msg.sender, price, remainingAmount, orderId, true);
        }
    }

    function cancelSellOrder(address market, address token, uint256 price, bytes32 orderId) external {
        OrderBookLinkedList.Order memory o = sellOrderBook[market][token][price].nodes[orderId].order;
        require(msg.sender == o.seller, "Not owner");

        IERC20(token).safeTransfer(msg.sender, o.amount);
        sellOrderBook[market][token][price].deleteNode(orderId);
        _sellOrders[market][token]._remove(msg.sender, orderId);
        _removePrice(market, token, price, true);
        emit OrderCancelled(market, token, msg.sender, price, orderId);
    }

    function cancelBuyOrder(address market, address token, uint256 price, bytes32 orderId) external {
        OrderBookLinkedList.Order memory o = buyOrderBook[market][token][price].nodes[orderId].order;
        require(msg.sender == o.seller, "Not owner");

        (address collateral, ) = _marketCollateral(market);
        if (collateral == address(0)) {
            Address.sendValue(payable(msg.sender), o.amount);
        } else {
            IERC20(collateral).safeTransfer(msg.sender, o.amount);
        }

        buyOrderBook[market][token][price].deleteNode(orderId);
        _buyOrders[market][token]._remove(msg.sender, orderId);
        _removePrice(market, token, price, false);
        emit OrderCancelled(market, token, msg.sender, price, orderId);
    }

    function collectFees(address collateralAsset) external onlyOwner {
        if (collateralAsset == address(0)) {
            uint256 f = accumulatedFeeNative;
            accumulatedFeeNative = 0;
            Address.sendValue(payable(owner()), f);
        } else {
            uint256 f = accumulatedFeeErc20[collateralAsset];
            accumulatedFeeErc20[collateralAsset] = 0;
            IERC20(collateralAsset).safeTransfer(owner(), f);
        }
    }

    function getBestBid(address market, address token) external view returns (uint256) {
        uint256[] storage prices = _buyPrices[market][token];
        if (prices.length == 0) return 0;
        for (uint256 i = 0; i < prices.length; i++) {
            if (buyOrderBook[market][token][prices[i]].length > 0) return prices[i];
        }
        return 0;
    }

    function getBestAsk(address market, address token) external view returns (uint256) {
        uint256[] storage prices = _sellPrices[market][token];
        if (prices.length == 0) return 0;
        for (uint256 i = 0; i < prices.length; i++) {
            if (sellOrderBook[market][token][prices[i]].length > 0) return prices[i];
        }
        return 0;
    }

    function _validate(address market, address token) internal view {
        require(marketFactory.isMarket(market), "Market");
        require(marketFactory.isOutcomeTokenForMarket(market, token), "Outcome");
    }

    function _marketCollateral(address market) internal view returns (address, uint8) {
        IMondaloreMarketCollateral m = IMondaloreMarketCollateral(market);
        return (m.collateralAddress(), m.collateralDecimals());
    }

    function _marketAndTokenDecimals(address market, address token) internal view returns (address collateral, uint8 tokenDec) {
        (collateral, ) = _marketCollateral(market);
        tokenDec = IERC20Metadata(token).decimals();
    }

    function _quote(uint256 amount, uint256 price, uint8 tokenDecimals) internal pure returns (uint256) {
        return (amount * price) / (10 ** uint256(tokenDecimals));
    }

    function _matchSellOrder(address market, address token, uint256 price, uint256 sellAmount)
        internal
        returns (uint256 remainingAmount)
    {
        remainingAmount = sellAmount;
        (address collateral, uint8 td) = _marketAndTokenDecimals(market, token);
        IERC20 tokenContract = IERC20(token);

        for (uint256 i = 0; i < buyOrderBook[market][token][price].length && remainingAmount > 0; ) {
            bytes32 head_ = buyOrderBook[market][token][price].head;
            uint256 buyCollateral = buyOrderBook[market][token][price].nodes[head_].order.amount;
            uint256 buyAmount = (buyCollateral * (10 ** uint256(td))) / price;

            OrderBookLinkedList.Order memory buyOrder = buyOrderBook[market][token][price].nodes[head_].order;

            if (remainingAmount >= buyAmount) {
                buyOrderBook[market][token][price].popHead();
                _buyOrders[market][token]._remove(buyOrder.seller, head_);
                _removePrice(market, token, price, false);

                tokenContract.safeTransfer(buyOrder.seller, buyAmount);
                _payCollateral(collateral, msg.sender, buyCollateral);

                emit OrderMatched(market, token, buyOrder.seller, msg.sender, price, buyAmount);
                remainingAmount -= buyAmount;
            } else {
                uint256 matchedCollateral = _quote(remainingAmount, price, td);
                buyOrderBook[market][token][price].nodes[head_].order.amount -= matchedCollateral;
                _buyOrders[market][token]._subVolume(buyOrder.seller, head_, matchedCollateral);

                tokenContract.safeTransfer(buyOrder.seller, remainingAmount);
                _payCollateral(collateral, msg.sender, matchedCollateral);

                emit OrderMatched(market, token, buyOrder.seller, msg.sender, price, remainingAmount);
                remainingAmount = 0;
            }
        }
    }

    function _matchBuyOrder(address market, address token, uint256 price, uint256 buyAmount, address collateral)
        internal
        returns (uint256 remainingAmount)
    {
        remainingAmount = buyAmount;
        (, uint8 td) = _marketAndTokenDecimals(market, token);
        IERC20 tokenContract = IERC20(token);

        for (uint256 i = 0; i < sellOrderBook[market][token][price].length && remainingAmount > 0; ) {
            bytes32 head_ = sellOrderBook[market][token][price].head;
            uint256 sellAmt = sellOrderBook[market][token][price].nodes[head_].order.amount;

            OrderBookLinkedList.Order memory sellOrder = sellOrderBook[market][token][price].nodes[head_].order;

            if (remainingAmount >= sellAmt) {
                uint256 matchedCollateral = _quote(sellAmt, price, td);

                sellOrderBook[market][token][price].popHead();
                _sellOrders[market][token]._remove(sellOrder.seller, head_);
                _removePrice(market, token, price, true);

                tokenContract.safeTransfer(msg.sender, sellAmt);
                _payCollateral(collateral, sellOrder.seller, matchedCollateral);

                emit OrderMatched(market, token, sellOrder.seller, msg.sender, price, sellAmt);
                remainingAmount -= sellAmt;
            } else {
                uint256 matchedCollateral = _quote(remainingAmount, price, td);

                sellOrderBook[market][token][price].nodes[head_].order.amount -= remainingAmount;
                _sellOrders[market][token]._subVolume(sellOrder.seller, head_, remainingAmount);

                tokenContract.safeTransfer(msg.sender, remainingAmount);
                _payCollateral(collateral, sellOrder.seller, matchedCollateral);

                emit OrderMatched(market, token, sellOrder.seller, msg.sender, price, remainingAmount);
                remainingAmount = 0;
            }
        }
    }

    function _payCollateral(address collateral, address to, uint256 amount) internal {
        if (collateral == address(0)) {
            Address.sendValue(payable(to), amount);
        } else {
            IERC20(collateral).safeTransfer(to, amount);
        }
    }

    function _addSellPrice(address market, address token, uint256 price) internal {
        if (!_activePrices[market][token][price]) {
            _activePrices[market][token][price] = true;
            _insertSorted(_sellPrices[market][token], price, true);
        }
    }

    function _addBuyPrice(address market, address token, uint256 price) internal {
        if (!_activePrices[market][token][price]) {
            _activePrices[market][token][price] = true;
            _insertSorted(_buyPrices[market][token], price, false);
        }
    }

    function _removePrice(address market, address token, uint256 price, bool isSell) internal {
        if (sellOrderBook[market][token][price].length == 0 && buyOrderBook[market][token][price].length == 0) {
            _activePrices[market][token][price] = false;
            if (isSell) {
                _removeFromArray(_sellPrices[market][token], price);
            } else {
                _removeFromArray(_buyPrices[market][token], price);
            }
        }
    }

    function _insertSorted(uint256[] storage arr, uint256 price, bool ascending) internal {
        uint256 i = 0;
        while (i < arr.length && (ascending ? arr[i] < price : arr[i] > price)) {
            i++;
        }
        arr.push(0);
        for (uint256 j = arr.length - 1; j > i; j--) {
            arr[j] = arr[j - 1];
        }
        arr[i] = price;
    }

    function _removeFromArray(uint256[] storage arr, uint256 price) internal {
        for (uint256 i = 0; i < arr.length; i++) {
            if (arr[i] == price) {
                arr[i] = arr[arr.length - 1];
                arr.pop();
                return;
            }
        }
    }

    receive() external payable {}
}

contracts/staking/MondaloreFeeVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/introspection/ERC165.sol";
import "../interfaces/IMondaloreFeeReceiver.sol";

/// @title MondaloreFeeVault
/// @notice Epoch-based fee-sharing vault. Users stake the Mondalore governance token and receive
///         sMondalore receipt tokens. A share of protocol fees (STAKER_SHARE_BPS of incoming fees)
///         is distributed to stakers pro-rata using the reward-per-token accumulator pattern.
///
/// Fee flow:
///   Market deposit → 1.2% protocol fee → feeRecipient (this vault)
///   Vault splits: STAKER_SHARE_BPS (20 bps = 0.2%) → stakers
///                 remainder (100 bps = 1.0%) → treasury (owner-withdrawable)
///
/// Epoch mechanics:
///   - Epochs advance automatically based on EPOCH_DURATION.
///   - Fees received during epoch N are claimable by stakers who were staked during epoch N.
///   - The accumulator is continuous (not snapshotted per epoch) — rewards accrue in real time
///     and are claimable at any time. Epochs are used for UI/reporting and lock enforcement.
///
/// Staking mechanics:
///   - Stake Mondalore → receive sMondalore 1:1.
///   - To unstake: call initiateUnstake(amount) → wait LOCK_DURATION → call completeUnstake().
///   - sMondalore is non-transferable (soul-bound) to prevent reward gaming.
///
/// Multi-token rewards:
///   - Any ERC20 or native ETH can be a reward token.
///   - Each reward token has its own accumulator.
///   - Owner registers reward tokens; vault accepts fees for registered tokens only.
contract MondaloreFeeVault is Ownable2Step, ReentrancyGuard, ERC165, IMondaloreFeeReceiver {
    using SafeERC20 for IERC20;

    // ─── Constants ────────────────────────────────────────────────────────────

    uint256 public constant BPS_DENOMINATOR = 10_000;
    /// @notice Share of incoming fees distributed to stakers (20 bps = 0.2%).
    uint256 public constant STAKER_SHARE_BPS = 20;
    /// @notice Precision multiplier for reward-per-token accumulator.
    uint256 public constant PRECISION = 1e18;

    // ─── Immutables ───────────────────────────────────────────────────────────

    /// @notice The token users stake (Mondalore governance/utility token).
    IERC20 public immutable stakeToken;
    /// @notice Duration of each epoch in seconds.
    uint256 public immutable epochDuration;
    /// @notice How long after initiateUnstake() before completeUnstake() is allowed.
    uint256 public immutable lockDuration;
    /// @notice Timestamp of vault deployment — epoch 0 start.
    uint256 public immutable deployedAt;

    // ─── sMondalore Receipt Token ──────────────────────────────────────────────────

    /// @notice sMONDO receipt token — minted on stake, burned on unstake.
    ///         Non-transferable: represents a locked staking position.
    sMondaloreToken public immutable receiptToken;

    // ─── Staking State ────────────────────────────────────────────────────────

    /// @notice Total Mondalore currently staked (excludes pending unstakes).
    uint256 public totalStaked;

    struct UnstakeRequest {
        uint256 amount;
        uint256 availableAt; // block.timestamp + lockDuration
    }
    /// @notice Pending unstake requests per user.
    mapping(address => UnstakeRequest) public unstakeRequests;

    // ─── Reward Token Registry ────────────────────────────────────────────────

    /// @notice List of registered reward tokens (address(0) = native ETH).
    address[] public rewardTokens;
    mapping(address => bool) public isRewardToken;

    // ─── Reward Accounting (per reward token) ─────────────────────────────────

    /// @notice Global reward-per-token accumulator. Increases whenever fees arrive.
    mapping(address => uint256) public rewardPerTokenStored;
    /// @notice Snapshot of rewardPerTokenStored at the time of user's last interaction.
    mapping(address => mapping(address => uint256)) public userRewardPerTokenPaid; // token => user => value
    /// @notice Pending claimable rewards per user per token.
    mapping(address => mapping(address => uint256)) public pendingRewards; // token => user => amount
    /// @notice Accumulated treasury share (owner-withdrawable) per token.
    mapping(address => uint256) public treasuryAccrued;
    /// @notice Fix #2: staker-share dust that truncated to zero — carried forward to next distribution.
    mapping(address => uint256) public stakerDust;

    // ─── Epoch Tracking ───────────────────────────────────────────────────────

    /// @notice Total fees received per epoch per token (for UI/analytics).
    mapping(uint256 => mapping(address => uint256)) public epochFees; // epoch => token => amount

    // ─── Events ───────────────────────────────────────────────────────────────

    event Staked(address indexed user, uint256 amount, uint256 epoch);
    event UnstakeInitiated(address indexed user, uint256 amount, uint256 availableAt);
    event UnstakeCompleted(address indexed user, uint256 amount);
    event UnstakeCancelled(address indexed user, uint256 amount);
    event RewardsClaimed(address indexed user, address indexed token, uint256 amount);
    event FeesReceived(address indexed token, uint256 total, uint256 stakerShare, uint256 treasuryShare, uint256 epoch);
    event RewardTokenAdded(address indexed token);
    event RewardTokenRemoved(address indexed token);
    event TreasuryWithdrawn(address indexed token, address indexed to, uint256 amount);

    // ─── Errors ───────────────────────────────────────────────────────────────

    error ZeroAmount();
    error NotRegisteredRewardToken();
    error NoUnstakeRequest();
    error LockNotExpired(uint256 availableAt);
    error InsufficientStake();
    error AlreadyRegistered();
    error NothingToClaim();
    error TransferFailed();
    error SoulBound();

    // ─── Modifiers ────────────────────────────────────────────────────────────

    /// @dev Updates the reward accumulator snapshot for a user across all reward tokens.
    modifier updateRewards(address user) {
        uint256 n = rewardTokens.length;
        for (uint256 i = 0; i < n; i++) {
            address token = rewardTokens[i];
            pendingRewards[token][user] = _earned(token, user);
            userRewardPerTokenPaid[token][user] = rewardPerTokenStored[token];
        }
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────────

    /// @param owner_         Initial owner (protocol multisig / DAO).
    /// @param stakeToken_    Mondalore governance token address.
    /// @param epochDuration_ Epoch length in seconds (e.g. 7 days = 604800).
    /// @param lockDuration_  Unstake lock in seconds (e.g. 7 days = 604800).
    constructor(
        address owner_,
        address stakeToken_,
        uint256 epochDuration_,
        uint256 lockDuration_
    ) Ownable(owner_) {
        require(stakeToken_ != address(0), "Zero stake token");
        require(epochDuration_ > 0, "Zero epoch");
        stakeToken = IERC20(stakeToken_);
        epochDuration = epochDuration_;
        lockDuration = lockDuration_;
        deployedAt = block.timestamp;
        receiptToken = new sMondaloreToken(address(this));
    }

    // ─── View: Epoch ──────────────────────────────────────────────────────────

    /// @notice Current epoch index (0-indexed, advances every epochDuration seconds).
    function currentEpoch() public view returns (uint256) {
        return (block.timestamp - deployedAt) / epochDuration;
    }

    // ─── View: Rewards ────────────────────────────────────────────────────────

    /// @notice Reward-per-token for a given reward token (current accumulator value).
    function rewardPerToken(address token) public view returns (uint256) {
        return rewardPerTokenStored[token];
    }

    /// @notice Total claimable rewards for `user` for a given `token`.
    function earned(address token, address user) external view returns (uint256) {
        return _earned(token, user);
    }

    /// @notice Total claimable rewards for `user` across all registered reward tokens.
    function earnedAll(address user)
        external
        view
        returns (address[] memory tokens, uint256[] memory amounts)
    {
        uint256 n = rewardTokens.length;
        tokens = new address[](n);
        amounts = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            tokens[i] = rewardTokens[i];
            amounts[i] = _earned(rewardTokens[i], user);
        }
    }

    // ─── Admin: Reward Token Registry ─────────────────────────────────────────

    /// @notice Register a new reward token. address(0) = native ETH.
    function addRewardToken(address token) external onlyOwner {
        if (isRewardToken[token]) revert AlreadyRegistered();
        isRewardToken[token] = true;
        rewardTokens.push(token);
        emit RewardTokenAdded(token);
    }

    /// @notice Remove a reward token (stops accepting new fees for it; existing rewards still claimable).
    function removeRewardToken(address token) external onlyOwner {
        if (!isRewardToken[token]) revert NotRegisteredRewardToken();
        isRewardToken[token] = false;
        uint256 n = rewardTokens.length;
        for (uint256 i = 0; i < n; i++) {
            if (rewardTokens[i] == token) {
                rewardTokens[i] = rewardTokens[n - 1];
                rewardTokens.pop();
                break;
            }
        }
        emit RewardTokenRemoved(token);
    }

    // ─── Admin: Treasury Withdrawal ───────────────────────────────────────────

    /// @notice Withdraw accumulated treasury share for a given token.
    function withdrawTreasury(address token, address to) external onlyOwner nonReentrant {
        require(to != address(0), "Zero to");
        uint256 amount = treasuryAccrued[token];
        if (amount == 0) revert NothingToClaim();
        treasuryAccrued[token] = 0;
        _sendToken(token, to, amount);
        emit TreasuryWithdrawn(token, to, amount);
    }

    // ─── ERC165 ───────────────────────────────────────────────────────────────

    function supportsInterface(bytes4 interfaceId) public view override returns (bool) {
        return interfaceId == type(IMondaloreFeeReceiver).interfaceId || super.supportsInterface(interfaceId);
    }

    // ─── IMondaloreFeeReceiver ─────────────────────────────────────────────────────

    /// @notice Called by markets to push ERC20 protocol fees atomically.
    ///         The market must have approved this vault for `amount` before calling.
    function receiveFees(address token, uint256 amount) external payable override nonReentrant {
        if (amount == 0) revert ZeroAmount();
        if (token == address(0)) {
            // Native ETH path — msg.value must match amount.
            if (!isRewardToken[address(0)]) revert NotRegisteredRewardToken();
            if (msg.value != amount) revert ZeroAmount();
            _distributeFees(address(0), amount);
        } else {
            if (!isRewardToken[token]) revert NotRegisteredRewardToken();
            // Pull from caller (market has approved us).
            IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
            _distributeFees(token, amount);
        }
    }

    // ─── Fee Intake (manual push) ─────────────────────────────────────────────

    /// @notice Push ERC20 fees into the vault manually. Caller must have approved this contract.
    /// @dev Use this when the fee source is not a market (e.g. orderbook fees, manual treasury top-up).
    function notifyFees(address token, uint256 amount) external nonReentrant {
        if (!isRewardToken[token]) revert NotRegisteredRewardToken();
        if (token == address(0)) revert NotRegisteredRewardToken(); // use notifyFeesETH for ETH
        if (amount == 0) revert ZeroAmount();

        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        _distributeFees(token, amount);
    }

    /// @notice Push native ETH fees into the vault.
    function notifyFeesETH() external payable nonReentrant {
        if (!isRewardToken[address(0)]) revert NotRegisteredRewardToken();
        if (msg.value == 0) revert ZeroAmount();
        _distributeFees(address(0), msg.value);
    }

    /// @notice Vault can receive ETH directly (e.g. from markets with ETH collateral).
    receive() external payable {
        // Silently accept ETH; owner must call notifyFeesETH or it sits as unallocated.
        // For automatic distribution, markets should call notifyFeesETH explicitly.
    }

    // ─── Staking ──────────────────────────────────────────────────────────────

    /// @notice Stake `amount` of Mondalore tokens. Receive sMondalore 1:1.
    /// @param amount Amount of Mondalore to stake.
    function stake(uint256 amount) external nonReentrant updateRewards(msg.sender) {
        if (amount == 0) revert ZeroAmount();

        stakeToken.safeTransferFrom(msg.sender, address(this), amount);
        totalStaked += amount;
        receiptToken.mint(msg.sender, amount);

        emit Staked(msg.sender, amount, currentEpoch());
    }

    /// @notice Begin the unstake process. Locks `amount` sMondalore for `lockDuration`.
    /// @dev Only one pending unstake request per user at a time.
    ///      Calling again while a request is pending adds to the existing request.
    function initiateUnstake(uint256 amount) external nonReentrant updateRewards(msg.sender) {
        if (amount == 0) revert ZeroAmount();
        uint256 staked = receiptToken.balanceOf(msg.sender);
        // Subtract any already-pending unstake from available balance.
        uint256 pending = unstakeRequests[msg.sender].amount;
        if (amount > staked - pending) revert InsufficientStake();

        unstakeRequests[msg.sender].amount += amount;
        unstakeRequests[msg.sender].availableAt = block.timestamp + lockDuration;

        // Reduce effective stake immediately so rewards stop accruing on this amount.
        totalStaked -= amount;

        emit UnstakeInitiated(msg.sender, amount, block.timestamp + lockDuration);
    }

    /// @notice Complete unstake after lock expires. Burns sMondalore, returns Mondalore.
    function completeUnstake() external nonReentrant updateRewards(msg.sender) {
        UnstakeRequest memory req = unstakeRequests[msg.sender];
        if (req.amount == 0) revert NoUnstakeRequest();
        if (block.timestamp < req.availableAt) revert LockNotExpired(req.availableAt);

        uint256 amount = req.amount;
        delete unstakeRequests[msg.sender];

        receiptToken.burn(msg.sender, amount);
        stakeToken.safeTransfer(msg.sender, amount);

        emit UnstakeCompleted(msg.sender, amount);
    }

    /// @notice Cancel a pending unstake request and re-activate the stake.
    function cancelUnstake() external nonReentrant updateRewards(msg.sender) {
        UnstakeRequest memory req = unstakeRequests[msg.sender];
        if (req.amount == 0) revert NoUnstakeRequest();

        uint256 amount = req.amount;
        delete unstakeRequests[msg.sender];

        // Re-add to effective stake.
        totalStaked += amount;

        emit UnstakeCancelled(msg.sender, amount);
    }

    // ─── Reward Claiming ──────────────────────────────────────────────────────

    /// @notice Claim all pending rewards for the caller across all reward tokens.
    function claimRewards() external nonReentrant updateRewards(msg.sender) {
        uint256 n = rewardTokens.length;
        bool claimed;
        for (uint256 i = 0; i < n; i++) {
            address token = rewardTokens[i];
            uint256 amount = pendingRewards[token][msg.sender];
            if (amount > 0) {
                pendingRewards[token][msg.sender] = 0;
                _sendToken(token, msg.sender, amount);
                emit RewardsClaimed(msg.sender, token, amount);
                claimed = true;
            }
        }
        if (!claimed) revert NothingToClaim();
    }

    /// @notice Claim rewards for a specific token only.
    function claimReward(address token) external nonReentrant updateRewards(msg.sender) {
        uint256 amount = pendingRewards[token][msg.sender];
        if (amount == 0) revert NothingToClaim();
        pendingRewards[token][msg.sender] = 0;
        _sendToken(token, msg.sender, amount);
        emit RewardsClaimed(msg.sender, token, amount);
    }

    // ─── Internal ─────────────────────────────────────────────────────────────

    /// @dev Splits incoming fees between staker accumulator and treasury.
    function _distributeFees(address token, uint256 amount) internal {
        uint256 stakerShare = (amount * STAKER_SHARE_BPS) / BPS_DENOMINATOR;
        uint256 treasuryShare = amount - stakerShare;

        // Accrue treasury portion.
        treasuryAccrued[token] += treasuryShare;

        // Fix #2: carry forward any previously truncated dust so it is distributed
        // as soon as the combined amount is large enough to produce a non-zero increment.
        if (stakerShare > 0 && totalStaked > 0) {
            uint256 effective = stakerShare + stakerDust[token];
            uint256 increment = (effective * PRECISION) / totalStaked;
            if (increment > 0) {
                rewardPerTokenStored[token] += increment;
                stakerDust[token] = 0;
            } else {
                // Still too small — accumulate dust for next round.
                stakerDust[token] += stakerShare;
                // Temporarily redirect this round's staker share to treasury so
                // the vault balance stays consistent; it will be reclaimed when
                // dust is eventually distributed.
                treasuryAccrued[token] += stakerShare;
                stakerShare = 0;
            }
        } else if (stakerShare > 0) {
            // No stakers — redirect staker share to treasury.
            treasuryAccrued[token] += stakerShare;
            stakerDust[token] = 0;
            stakerShare = 0;
        }

        uint256 epoch = currentEpoch();
        epochFees[epoch][token] += amount;

        emit FeesReceived(token, amount, stakerShare, treasuryShare, epoch);
    }

    /// @dev Compute earned rewards for a user for a given token.
    function _earned(address token, address user) internal view returns (uint256) {
        uint256 stakedBalance = receiptToken.balanceOf(user);
        // Subtract pending unstake — those tokens are no longer earning.
        uint256 pendingUnstake = unstakeRequests[user].amount;
        uint256 effectiveStake = stakedBalance > pendingUnstake ? stakedBalance - pendingUnstake : 0;

        return pendingRewards[token][user]
            + (effectiveStake * (rewardPerTokenStored[token] - userRewardPerTokenPaid[token][user])) / PRECISION;
    }

    /// @dev Send `token` (ERC20 or ETH) to `to`.
    function _sendToken(address token, address to, uint256 amount) internal {
        if (token == address(0)) {
            (bool ok, ) = payable(to).call{value: amount}("");
            if (!ok) revert TransferFailed();
        } else {
            IERC20(token).safeTransfer(to, amount);
        }
    }
}

// ─── sMondalore Receipt Token ──────────────────────────────────────────────────────

/// @title sMondaloreToken
/// @notice Non-transferable ERC20 receipt token representing a staked Mondalore position.
///         Minted 1:1 on stake, burned on unstake. Only the vault can mint/burn.
contract sMondaloreToken is ERC20 {
    address public immutable vault;

    error OnlyVault();
    error SoulBound();

    modifier onlyVault() {
        if (msg.sender != vault) revert OnlyVault();
        _;
    }

    constructor(address vault_) ERC20("Staked MONDO", "sMONDO") {
        vault = vault_;
    }

    function mint(address to, uint256 amount) external onlyVault {
        _mint(to, amount);
    }

    function burn(address from, uint256 amount) external onlyVault {
        _burn(from, amount);
    }

    /// @dev Block all transfers — sMondalore is soul-bound to the staker.
    function transfer(address, uint256) public pure override returns (bool) {
        revert SoulBound();
    }

    function transferFrom(address, address, uint256) public pure override returns (bool) {
        revert SoulBound();
    }

    function approve(address, uint256) public pure override returns (bool) {
        revert SoulBound();
    }
}

contracts/token/MondaloreOutcomeToken.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/// @title MondaloreOutcomeToken
/// @notice ERC20 outcome share; decimals match market collateral (e.g. 6 USDC, 18 ETH).
contract MondaloreOutcomeToken is ERC20, Ownable {
    uint8 private immutable _decimals;

    constructor(string memory name_, string memory symbol_, uint8 decimals_, address initialOwner)
        ERC20(name_, symbol_)
        Ownable(initialOwner)
    {
        _decimals = decimals_;
    }

    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
    }

    function burnFrom(address from, uint256 amount) external {
        if (msg.sender != from) {
            _spendAllowance(from, msg.sender, amount);
        }
        _burn(from, amount);
    }

    function decimals() public view override returns (uint8) {
        return _decimals;
    }
}

contracts/token/MondaloreToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable2Step.sol";

/// @title MondaloreToken
/// @notice MONDO protocol governance / utility token ($MONDO).
///         18 decimals. Owner can mint (capped at MAX_SUPPLY).
///         Used as the staking token in MondaloreFeeVault.
contract MondaloreToken is ERC20, Ownable2Step {
    uint256 public constant MAX_SUPPLY = 1_000_000_000 * 1e18; // 1 billion

    error MaxSupplyExceeded();

    constructor(address owner_, uint256 initialMint) ERC20("MONDO", "MONDO") Ownable(owner_) {
        if (initialMint > 0) {
            if (initialMint > MAX_SUPPLY) revert MaxSupplyExceeded();
            _mint(owner_, initialMint);
        }
    }

    function mint(address to, uint256 amount) external onlyOwner {
        if (totalSupply() + amount > MAX_SUPPLY) revert MaxSupplyExceeded();
        _mint(to, amount);
    }

    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
    }
}

